// Scene -> Lua / XML. Output goes to a *separate generated file* that is wholly owned by the tool (marked with
// GENERATED_MARKER). User-maintained code never lives in it; the writer refuses to overwrite an unmarked file.
import { isContainer, sanitizeName, type Anchor, type Rgba, type Scene, type SceneNode } from "./scene";
import { solve } from "./layout";

export const GENERATED_MARKER = "@generated by WoW Forever Studio";
export const isGenerated = (text: string) => text.slice(0, 400).includes(GENERATED_MARKER);

const num = (n: number): string => { const r = Math.round(n * 1000) / 1000; return Object.is(r, -0) ? "0" : String(r); };
const rgba = (c: Rgba) => c.map(num).join(", ");
const luaStr = (s: string) => '"' + s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n").replace(/\r/g, "") + '"';
const xmlEsc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

export interface Generated { lua: string; xml: string; warnings: string[]; luaPath: string; xmlPath: string }

/** Parents and anchor targets before dependants, otherwise stable creation order. */
export function emitOrder(scene: Scene): string[] {
  const out: string[] = [], seen = new Set<string>(), stack = new Set<string>();
  const visit = (id: string) => {
    if (seen.has(id) || stack.has(id)) return;
    stack.add(id);
    const n = scene.nodes[id]!;
    if (n.parent) visit(n.parent);
    for (const a of n.anchors) if (a.relTo && scene.nodes[a.relTo]) visit(a.relTo);
    stack.delete(id);
    seen.add(id);
    out.push(id);
  };
  scene.order.forEach(visit);
  return out;
}

export function generate(scene: Scene): Generated {
  const warnings: string[] = [];
  const solved = solve(scene);
  for (const [id, msg] of solved.errors) warnings.push(`${scene.nodes[id]?.name ?? id}: ${msg}`);
  const deco = Object.values(scene.nodes).filter((n) => n.border || n.shadow || n.pulse);
  if (deco.length) warnings.push(`${deco.length} element(s) use border/shadow/pulse, which are emitted in Lua only (not in the XML output).`);
  const sim = Object.values(scene.nodes).filter((n) => n.bind || n.repeat);
  if (sim.length) warnings.push(`${sim.length} element(s) have preview-only bindings/repeaters; these are not emitted. Wire real events and unit APIs in your own code.`);
  const base = sanitizeName(scene.name);
  return { lua: genLua(scene, base, warnings), xml: genXml(scene, base), warnings, luaPath: `Generated/${base}.lua`, xmlPath: `Generated/${base}.xml` };
}

const HIDE_UNTIL_WIRED = new Set(["lowHealth", "showIfCasting", "castUninterruptible", "auraIcon", "combat"]);

/** Border / shadow / pulse / blend. Emitted for Lua only (the XML output does not carry them). */
function decorations(n: SceneNode, v: string, L: string[], isFrame: boolean) {
  if (n.shadow && isFrame) {
    L.push(`    ${v}.shadow = ${v}:CreateTexture(nil, "BACKGROUND", nil, -8)`);
    L.push(`    ${v}.shadow:SetPoint("TOPLEFT", ${v}, "TOPLEFT", ${num(-n.shadow.size)}, ${num(n.shadow.size)})`);
    L.push(`    ${v}.shadow:SetPoint("BOTTOMRIGHT", ${v}, "BOTTOMRIGHT", ${num(n.shadow.size)}, ${num(-n.shadow.size)})`);
    L.push(`    ${v}.shadow:SetColorTexture(0, 0, 0, ${num(n.shadow.alpha)})`);
  }
  if (n.border && isFrame) {
    const b = n.border, c = rgba(b.color);
    L.push(`    ${v}.edge = {}`);
    for (const [k, pts, size] of [["top", ["TOPLEFT", "TOPRIGHT"], "H"], ["bottom", ["BOTTOMLEFT", "BOTTOMRIGHT"], "H"], ["left", ["TOPLEFT", "BOTTOMLEFT"], "W"], ["right", ["TOPRIGHT", "BOTTOMRIGHT"], "W"]] as const) {
      L.push(`    ${v}.edge.${k} = ${v}:CreateTexture(nil, "BORDER")`);
      L.push(`    ${v}.edge.${k}:SetColorTexture(${c})`);
      for (const p of pts) L.push(`    ${v}.edge.${k}:SetPoint(${luaStr(p)}, ${v}, ${luaStr(p)})`);
      L.push(`    ${v}.edge.${k}:Set${size === "H" ? "Height" : "Width"}(${num(b.size)})`);
    }
  }
  if (n.blend === "ADD" && !isFrame) L.push(`    ${v}:SetBlendMode("ADD")`);
  if (n.pulse) {
    L.push(`    ${v}.pulse = ${v}:CreateAnimationGroup()`);
    L.push(`    ${v}.pulse:SetLooping("BOUNCE")`);
    L.push(`    do local a = ${v}.pulse:CreateAnimation("Alpha"); a:SetFromAlpha(${num(n.pulse.high)}); a:SetToAlpha(${num(n.pulse.low)}); a:SetDuration(${num(n.pulse.period / 2)}) end`);
    L.push(`    ${v}.pulse:Play()`);
  }
  if (n.bind && HIDE_UNTIL_WIRED.has(n.bind.stat)) {
    L.push(`    ${v}:Hide() -- preview-bound (${n.bind.stat}): hidden until your own code shows it`);
  }
}

function genLua(scene: Scene, base: string, warnings: string[]): string {
  const L: string[] = [];
  const key = (id: string) => `f.${scene.nodes[id]!.name}`;
  const parentVar = (n: SceneNode) => (n.parent ? key(n.parent) : "parent");
  L.push(`-- ${GENERATED_MARKER}. DO NOT EDIT: this file is overwritten on every generate.`);
  L.push(`-- Source scene: Design/${base}.scene.json (scene model v${scene.version}).`);
  L.push(`-- Hand-written logic belongs in your own files: call ns.UI.Create${base}() and use the returned table.`);
  L.push(`local addonName, ns = ...`);
  L.push(`ns.UI = ns.UI or {}`);
  L.push(``);
  L.push(`--- Builds "${scene.name}". Returns a table of frames/regions keyed by element name.`);
  L.push(`function ns.UI.Create${base}(parent)`);
  L.push(`    parent = parent or UIParent`);
  L.push(`    local f = {}`);
  const anchorLine = (n: SceneNode, a: Anchor) => {
    const rel = a.relTo && scene.nodes[a.relTo] ? key(a.relTo) : parentVar(n);
    return `    ${key(n.id)}:SetPoint(${luaStr(a.point)}, ${rel}, ${luaStr(a.relPoint)}, ${num(a.x)}, ${num(a.y)})`;
  };
  for (const id of emitOrder(scene)) {
    const n = scene.nodes[id]!;
    const v = key(id), p = parentVar(n);
    const gname = n.global ? luaStr(n.name) : "nil";
    L.push(``);
    L.push(`    -- ${n.name} (${n.kind})`);
    if (n.kind === "frame" || n.kind === "button" || n.kind === "statusbar") {
      const type = n.kind === "frame" ? "Frame" : n.kind === "button" ? "Button" : "StatusBar";
      L.push(`    ${v} = CreateFrame(${luaStr(type)}, ${gname}, ${p})`);
      L.push(`    ${v}:SetSize(${num(n.width)}, ${num(n.height)})`);
      if (n.strata !== "MEDIUM") L.push(`    ${v}:SetFrameStrata(${luaStr(n.strata)})`);
      if (n.level !== 0) L.push(`    ${v}:SetFrameLevel(${p}:GetFrameLevel() + ${n.level})`);
      for (const a of n.anchors) L.push(anchorLine(n, a));
      if (n.kind === "statusbar") {
        L.push(`    ${v}:SetStatusBarTexture(${luaStr(n.texture || "Interface\\TargetingFrame\\UI-StatusBar")})`);
        L.push(`    ${v}:SetMinMaxValues(${num(n.min)}, ${num(n.max)})`);
        L.push(`    ${v}:SetValue(${num(n.value)})`);
        L.push(`    ${v}:SetStatusBarColor(${rgba(n.barColor)})`);
      }
      if (n.color[3] > 0) {
        L.push(`    ${v}.bg = ${v}:CreateTexture(nil, "BACKGROUND")`);
        L.push(`    ${v}.bg:SetAllPoints(${v})`);
        L.push(`    ${v}.bg:SetColorTexture(${rgba(n.color)})`);
      }
      if (n.kind === "button" && n.text) {
        L.push(`    ${v}.label = ${v}:CreateFontString(nil, "OVERLAY")`);
        L.push(`    ${v}.label:SetFont(${luaStr(n.font)}, ${num(n.fontSize)}, ${luaStr(n.outline)})`);
        L.push(`    ${v}.label:SetPoint("CENTER")`);
        L.push(`    ${v}.label:SetText(${luaStr(n.text)})`);
      }
      if (n.alpha !== 1) L.push(`    ${v}:SetAlpha(${num(n.alpha)})`);
      decorations(n, v, L, true);
      if (n.hidden) L.push(`    ${v}:Hide()`);
    } else if (n.kind === "texture") {
      L.push(`    ${v} = ${p}:CreateTexture(${gname}, ${luaStr(n.layer)})`);
      L.push(`    ${v}:SetSize(${num(n.width)}, ${num(n.height)})`);
      for (const a of n.anchors) L.push(anchorLine(n, a));
      L.push(n.texture ? `    ${v}:SetTexture(${luaStr(n.texture)})` : `    ${v}:SetColorTexture(${rgba(n.color)})`);
      if (n.alpha !== 1) L.push(`    ${v}:SetAlpha(${num(n.alpha)})`);
      decorations(n, v, L, false);
      if (n.hidden) L.push(`    ${v}:Hide()`);
    } else {
      L.push(`    ${v} = ${p}:CreateFontString(${gname}, ${luaStr(n.layer)})`);
      L.push(`    ${v}:SetFont(${luaStr(n.font)}, ${num(n.fontSize)}, ${luaStr(n.outline)})`);
      L.push(`    ${v}:SetSize(${num(n.width)}, ${num(n.height)})`);
      for (const a of n.anchors) L.push(anchorLine(n, a));
      L.push(`    ${v}:SetJustifyH(${luaStr(n.justify)})`);
      L.push(`    ${v}:SetTextColor(${rgba(n.color)})`);
      L.push(`    ${v}:SetText(${luaStr(n.text)})`);
      if (n.alpha !== 1) L.push(`    ${v}:SetAlpha(${num(n.alpha)})`);
      if (n.hidden) L.push(`    ${v}:Hide()`);
    }
    if (!n.anchors.length) warnings.push(`${n.name}: no anchor, so SetPoint is not emitted and the client will not show it`);
  }
  L.push(``);
  L.push(`    return f`);
  L.push(`end`);
  L.push(``);
  return L.join("\n");
}

function genXml(scene: Scene, base: string): string {
  const xn = (n: SceneNode) => `${base}_${n.name}`;
  const anchors = (n: SceneNode, ind: string) => {
    if (!n.anchors.length) return "";
    const items = n.anchors.map((a) => {
      const rel = a.relTo && scene.nodes[a.relTo] ? ` relativeTo="${xmlEsc(xn(scene.nodes[a.relTo]!))}"` : "";
      return `${ind}  <Anchor point="${a.point}"${rel} relativePoint="${a.relPoint}"><Offset x="${num(a.x)}" y="${num(a.y)}"/></Anchor>`;
    });
    return `${ind}<Anchors>\n${items.join("\n")}\n${ind}</Anchors>\n`;
  };
  const size = (n: SceneNode, ind: string) => `${ind}<Size x="${num(n.width)}" y="${num(n.height)}"/>\n`;
  const colorEl = (tag: string, c: Rgba, ind: string) => `${ind}<${tag} r="${num(c[0])}" g="${num(c[1])}" b="${num(c[2])}" a="${num(c[3])}"/>\n`;

  const regions = (n: SceneNode, ind: string): string => {
    const kids = scene.order.map((i) => scene.nodes[i]!).filter((c) => c.parent === n.id && (c.kind === "texture" || c.kind === "fontstring"));
    const bg = isContainer(n.kind) && n.color[3] > 0;
    if (!kids.length && !bg) return "";
    let s = `${ind}<Layers>\n`;
    if (bg) s += `${ind}  <Layer level="BACKGROUND">\n${ind}    <Texture setAllPoints="true">\n${colorEl("Color", n.color, ind + "      ")}${ind}    </Texture>\n${ind}  </Layer>\n`;
    for (const c of kids) {
      const hid = c.hidden ? ` hidden="true"` : "";
      s += `${ind}  <Layer level="${c.layer}">\n`;
      if (c.kind === "texture") {
        s += `${ind}    <Texture name="${xmlEsc(xn(c))}"${c.texture ? ` file="${xmlEsc(c.texture)}"` : ""}${c.alpha !== 1 ? ` alpha="${num(c.alpha)}"` : ""}${hid}>\n${size(c, ind + "      ")}${anchors(c, ind + "      ")}${c.texture ? "" : colorEl("Color", c.color, ind + "      ")}${ind}    </Texture>\n`;
      } else {
        s += `${ind}    <FontString name="${xmlEsc(xn(c))}" font="${xmlEsc(c.font)}" text="${xmlEsc(c.text)}" justifyH="${c.justify}"${c.outline ? ` outline="${c.outline === "THICKOUTLINE" ? "THICK" : "NORMAL"}"` : ""}${hid}>\n${size(c, ind + "      ")}${anchors(c, ind + "      ")}${colorEl("Color", c.color, ind + "      ")}${ind}    </FontString>\n`;
      }
      s += `${ind}  </Layer>\n`;
    }
    return s + `${ind}</Layers>\n`;
  };

  const frame = (n: SceneNode, ind: string): string => {
    const tag = n.kind === "button" ? "Button" : n.kind === "statusbar" ? "StatusBar" : "Frame";
    const attrs = [`name="${xmlEsc(xn(n))}"`, n.parent ? "" : `parent="UIParent"`, n.strata !== "MEDIUM" ? `frameStrata="${n.strata}"` : "", n.level ? `frameLevel="${n.level}"` : "", n.alpha !== 1 ? `alpha="${num(n.alpha)}"` : "", n.hidden ? `hidden="true"` : "", n.kind === "button" && n.text ? `text="${xmlEsc(n.text)}"` : "", n.kind === "statusbar" ? `minValue="${num(n.min)}" maxValue="${num(n.max)}" defaultValue="${num(n.value)}"` : ""].filter(Boolean).join(" ");
    let s = `${ind}<${tag} ${attrs}>\n${size(n, ind + "  ")}${anchors(n, ind + "  ")}${regions(n, ind + "  ")}`;
    if (n.kind === "statusbar") s += `${ind}  <BarTexture file="${xmlEsc(n.texture || "Interface\\TargetingFrame\\UI-StatusBar")}"/>\n${colorEl("BarColor", n.barColor, ind + "  ")}`;
    const kids = scene.order.map((i) => scene.nodes[i]!).filter((c) => c.parent === n.id && isContainer(c.kind));
    if (kids.length) s += `${ind}  <Frames>\n${kids.map((c) => frame(c, ind + "    ")).join("")}${ind}  </Frames>\n`;
    return s + `${ind}</${tag}>\n`;
  };
  const roots = scene.order.map((i) => scene.nodes[i]!).filter((n) => !n.parent && isContainer(n.kind));
  return `<Ui xmlns="http://www.blizzard.com/wow/ui/">\n  <!-- ${GENERATED_MARKER}. DO NOT EDIT. Every element gets the global name "${base}_<name>". Top-level textures/font strings need a frame parent and are only emitted in the Lua output. -->\n${roots.map((r) => frame(r, "  ")).join("")}</Ui>\n`;
}
